INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-first-sentences-a1-02-01', 'lesson-first-sentences-a1-02', 1, 'sentence', 'Are you Brazilian?', 'Você é brasileiro?', '/ɑːr juː brəˈzɪliən/', 'Pergunta com "to be": o verbo vem antes do sujeito ("you are" → "are you?").', '[]'::jsonb, '[{"surface":"Are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"Brazilian","pos":"adjective","ipa":"/brəˈzɪliən/","gloss":"brasileiro"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-02-02', 'lesson-first-sentences-a1-02', 2, 'sentence', 'Is she your sister?', 'Ela é sua irmã?', '/ɪz ʃiː jʊr ˈsɪstər/', 'Com he/she/it o verbo é "is": "she is" → "is she?".', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"sister","pos":"noun","ipa":"/ˈsɪstər/","gloss":"irmã"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-02-03', 'lesson-first-sentences-a1-02', 3, 'sentence', 'Where are you from?', 'De onde você é?', '/wɛr ɑːr juː frʌm/', 'Palavra de pergunta + "to be" + sujeito. "From" vai para o fim.', '[]'::jsonb, '[{"surface":"Where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-02-04', 'lesson-first-sentences-a1-02', 4, 'sentence', 'How old are you?', 'Quantos anos você tem?', '/haʊ oʊld ɑːr juː/', 'Idade usa "to be" em inglês: "I am twenty", nunca "I have twenty".', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-02-05', 'lesson-first-sentences-a1-02', 5, 'sentence', 'How are you today?', 'Como você está hoje?', '/haʊ ɑːr juː təˈdeɪ/', 'Resposta comum: "I''m fine, thanks. And you?".', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-02-06', 'lesson-first-sentences-a1-02', 6, 'sentence', 'Is this seat free?', 'Este lugar está livre?', '/ɪz ðɪs siːt friː/', '"This" aponta para algo perto. "Free" = livre, desocupado.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"seat","pos":"noun","ipa":"/siːt/","gloss":"assento"},{"surface":"free","pos":"adjective","ipa":"/friː/","gloss":"livre, disponível"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-02-07', 'lesson-first-sentences-a1-02', 7, 'sentence', 'Are they at home?', 'Eles estão em casa?', '/ɑːr ðeɪ æt hoʊm/', '"They are" → "are they?". "At home" sem artigo.', '[]'::jsonb, '[{"surface":"Are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-02-08', 'lesson-first-sentences-a1-02', 8, 'sentence', 'What is your email?', 'Qual é o seu e-mail?', '/wʌt ɪz jʊr ˈiːmeɪl/', '"What is" (What''s) + possessivo + coisa.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"email","pos":"noun","ipa":"/ˈiːmeɪl/","gloss":"e-mail"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-02-09', 'lesson-first-sentences-a1-02', 9, 'sentence', 'Who is that man?', 'Quem é aquele homem?', '/huː ɪz ðæt mæn/', '"Who" = quem. "That" aponta para algo longe.', '[]'::jsonb, '[{"surface":"Who","pos":"pronoun","ipa":"/huː/","gloss":"quem"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"man","pos":"noun","ipa":"/mæn/","gloss":"homem"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-02-10', 'lesson-first-sentences-a1-02', 10, 'sentence', 'Yes, I am.', 'Sim, sou.', '/jɛs aɪ æm/', 'Resposta curta: repete o sujeito e o verbo, sem contração no afirmativo ("Yes, I''m" está errado).', '[]'::jsonb, '[{"surface":"Yes","pos":"interjection","ipa":"/jɛs/","gloss":"sim"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"am","pos":"auxiliary verb","ipa":"/æm/","gloss":"sou, estou"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-first-sentences-a1-03-01', 'lesson-first-sentences-a1-03', 1, 'sentence', 'I''m not tired.', 'Não estou cansado.', '/aɪm nɑːt ˈtaɪərd/', 'Negativa: "to be" + "not". Com "I" só existe "I''m not".', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"tired","pos":"adjective","ipa":"/ˈtaɪərd/","gloss":"cansado"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-03-02', 'lesson-first-sentences-a1-03', 2, 'sentence', 'He isn''t at work today.', 'Ele não está no trabalho hoje.', '/hiː ˈɪzənt æt wɜːrk təˈdeɪ/', '"Is not" contrai para "isn''t".', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"isn''t","pos":"auxiliary verb","ipa":"/ˈɪzənt/","gloss":"não é, não está"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-03-03', 'lesson-first-sentences-a1-03', 3, 'sentence', 'We aren''t ready yet.', 'Ainda não estamos prontos.', '/wiː ɑːrnt ˈrɛdi jɛt/', '"Are not" → "aren''t". "Yet" no fim = ainda (em negativas).', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"aren''t","pos":"verb","ipa":"/ɑːrnt/","gloss":"não são, não estão (are not)"},{"surface":"ready","pos":"adjective","ipa":"/ˈrɛdi/","gloss":"pronto"},{"surface":"yet","pos":"adverb","ipa":"/jɛt/","gloss":"ainda"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-03-04', 'lesson-first-sentences-a1-03', 4, 'sentence', 'It isn''t expensive.', 'Não é caro.', '/ɪt ˈɪzənt ɪkˈspɛnsɪv/', '"It" para coisas. "Expensive" = caro; "cheap" = barato.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"isn''t","pos":"auxiliary verb","ipa":"/ˈɪzənt/","gloss":"não é, não está"},{"surface":"expensive","pos":"adjective","ipa":"/ɪkˈspɛnsɪv/","gloss":"caro"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-03-05', 'lesson-first-sentences-a1-03', 5, 'sentence', 'They aren''t my friends.', 'Eles não são meus amigos.', '/ðeɪ ɑːrnt maɪ frɛndz/', 'Plural com "are": "they aren''t".', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"aren''t","pos":"verb","ipa":"/ɑːrnt/","gloss":"não são, não estão (are not)"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"friends","pos":"noun","ipa":"/frɛndz/","gloss":"amigos"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-03-06', 'lesson-first-sentences-a1-03', 6, 'sentence', 'No, she isn''t.', 'Não, ela não é.', '/noʊ ʃiː ˈɪzənt/', 'Resposta curta negativa: sujeito + verbo contraído com "not".', '[]'::jsonb, '[{"surface":"No","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"isn''t","pos":"auxiliary verb","ipa":"/ˈɪzənt/","gloss":"não é, não está"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-03-07', 'lesson-first-sentences-a1-03', 7, 'sentence', 'That''s not my bag.', 'Essa não é minha bolsa.', '/ðæts nɑːt maɪ bæɡ/', 'Outra forma de negar: "that''s not" = "that isn''t".', '[]'::jsonb, '[{"surface":"That''s","pos":"pronoun","ipa":"/ðæts/","gloss":"isso é"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-03-08', 'lesson-first-sentences-a1-03', 8, 'sentence', 'I''m not from here.', 'Não sou daqui.', '/aɪm nɑːt frʌm hɪr/', 'Útil para pedir paciência ou ajuda.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-03-09', 'lesson-first-sentences-a1-03', 9, 'sentence', 'The store isn''t open on Sunday.', 'A loja não abre no domingo.', '/ðə stɔːr ˈɪzənt ˈoʊpən ɑːn ˈsʌndeɪ/', 'Horário com "to be" + adjetivo: "open", "closed".', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"store","pos":"noun","ipa":"/stɔːr/","gloss":"loja, mercado"},{"surface":"isn''t","pos":"auxiliary verb","ipa":"/ˈɪzənt/","gloss":"não é, não está"},{"surface":"open","pos":"verb","ipa":"/ˈoʊpən/","gloss":"abrir"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Sunday","pos":"proper noun","ipa":"/ˈsʌndeɪ/","gloss":"domingo"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-03-10', 'lesson-first-sentences-a1-03', 10, 'sentence', 'You''re not late.', 'Você não está atrasado.', '/jʊr nɑːt leɪt/', '"You''re not" e "you aren''t" são equivalentes.', '[]'::jsonb, '[{"surface":"You''re","pos":"pronoun","ipa":"/jʊr/","gloss":"você está, você é"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-first-sentences-a1-04-01', 'lesson-first-sentences-a1-04', 1, 'sentence', 'There is a bank near here.', 'Tem um banco perto daqui.', '/ðɛr ɪz ə bæŋk nɪr hɪr/', '"There is" = há, tem (singular). Em português dizemos "tem".', '[]'::jsonb, '[{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"bank","pos":"noun","ipa":"/bæŋk/","gloss":"banco"},{"surface":"near","pos":"preposition","ipa":"/nɪr/","gloss":"perto de"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-04-02', 'lesson-first-sentences-a1-04', 2, 'sentence', 'There are two bedrooms.', 'Tem dois quartos.', '/ðɛr ɑːr tuː ˈbɛdruːmz/', '"There are" para plural.', '[]'::jsonb, '[{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"bedrooms","pos":"noun","ipa":"/ˈbɛdruːmz/","gloss":"quartos"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-04-03', 'lesson-first-sentences-a1-04', 3, 'sentence', 'Is there a pharmacy nearby?', 'Tem farmácia por perto?', '/ɪz ðɛr ə ˈfɑːrməsi ˌnɪrˈbaɪ/', 'Pergunta: "Is there…?" / "Are there…?".', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"pharmacy","pos":"noun","ipa":"/ˈfɑːrməsi/","gloss":"farmácia"},{"surface":"nearby","pos":"adverb","ipa":"/ˌnɪrˈbaɪ/","gloss":"por perto"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-04-04', 'lesson-first-sentences-a1-04', 4, 'sentence', 'There isn''t any milk.', 'Não tem leite nenhum.', '/ðɛr ˈɪzənt ˈɛni mɪlk/', 'Negativa com "any": "there isn''t any" + incontável.', '[]'::jsonb, '[{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"isn''t","pos":"auxiliary verb","ipa":"/ˈɪzənt/","gloss":"não é, não está"},{"surface":"any","pos":"determiner","ipa":"/ˈɛni/","gloss":"algum, alguma"},{"surface":"milk","pos":"noun","ipa":"/mɪlk/","gloss":"leite"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-04-05', 'lesson-first-sentences-a1-04', 5, 'sentence', 'Are there any questions?', 'Alguma pergunta?', '/ɑːr ðɛr ˈɛni ˈkwɛstʃənz/', '"Any" em perguntas = algum. Frase clássica de professor.', '[]'::jsonb, '[{"surface":"Are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"any","pos":"determiner","ipa":"/ˈɛni/","gloss":"algum, alguma"},{"surface":"questions","pos":"noun","ipa":"/ˈkwɛstʃənz/","gloss":"perguntas, dúvidas"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-04-06', 'lesson-first-sentences-a1-04', 6, 'sentence', 'There''s a problem with my room.', 'Tem um problema com meu quarto.', '/ðɛrz ə ˈprɑːbləm wɪð maɪ ruːm/', '"There''s" = "there is" contraído, muito usado na fala.', '[]'::jsonb, '[{"surface":"There''s","pos":"pronoun","ipa":"/ðɛrz/","gloss":"há, tem (there is)"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"problem","pos":"noun","ipa":"/ˈprɑːbləm/","gloss":"problema"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"room","pos":"noun","ipa":"/ruːm/","gloss":"quarto"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-04-07', 'lesson-first-sentences-a1-04', 7, 'sentence', 'There are many people here.', 'Tem muita gente aqui.', '/ðɛr ɑːr ˈmɛni ˈpiːpəl hɪr/', '"People" já é plural: "there are many people".', '[]'::jsonb, '[{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"many","pos":"determiner","ipa":"/ˈmɛni/","gloss":"muitos (how many)"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-04-08', 'lesson-first-sentences-a1-04', 8, 'sentence', 'There aren''t any seats left.', 'Não sobrou nenhum lugar.', '/ðɛr ɑːrnt ˈɛni siːts lɛft/', '"Left" aqui = restante, sobrando.', '[]'::jsonb, '[{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"aren''t","pos":"verb","ipa":"/ɑːrnt/","gloss":"não são, não estão (are not)"},{"surface":"any","pos":"determiner","ipa":"/ˈɛni/","gloss":"algum, alguma"},{"surface":"seats","pos":"noun","ipa":"/siːts/","gloss":"assentos"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-04-09', 'lesson-first-sentences-a1-04', 9, 'sentence', 'There is a lot of traffic today.', 'Tem muito trânsito hoje.', '/ðɛr ɪz ə lɑːt ʌv ˈtræfɪk təˈdeɪ/', '"A lot of" serve para contável e incontável.', '[]'::jsonb, '[{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"lot","pos":"noun","ipa":"/lɑːt/","gloss":"muito (a lot)"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"traffic","pos":"noun","ipa":"/ˈtræfɪk/","gloss":"trânsito"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-04-10', 'lesson-first-sentences-a1-04', 10, 'sentence', 'There is someone at the door.', 'Tem alguém na porta.', '/ðɛr ɪz ˈsʌmwʌn æt ðə dɔːr/', '"Someone" = alguém. Verbo no singular.', '[]'::jsonb, '[{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"someone","pos":"pronoun","ipa":"/ˈsʌmwʌn/","gloss":"alguém"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"door","pos":"noun","ipa":"/dɔːr/","gloss":"porta"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-first-sentences-a1-05-01', 'lesson-first-sentences-a1-05', 1, 'sentence', 'This is my brother.', 'Este é meu irmão.', '/ðɪs ɪz maɪ ˈbrʌðər/', '"This is" para apresentar alguém. "My" = meu/minha.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"brother","pos":"noun","ipa":"/ˈbrʌðər/","gloss":"irmão"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-05-02', 'lesson-first-sentences-a1-05', 2, 'sentence', 'Is this your phone?', 'Este celular é seu?', '/ɪz ðɪs jʊr foʊn/', '"Your" = seu/sua/de vocês. Não muda com gênero ou número.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-05-03', 'lesson-first-sentences-a1-05', 3, 'sentence', 'His name is Carlos.', 'O nome dele é Carlos.', '/hɪz neɪm ɪz ˈkɑːrloʊs/', '"His" = dele. O possessivo concorda com o dono, não com a coisa.', '[]'::jsonb, '[{"surface":"His","pos":"determiner","ipa":"/hɪz/","gloss":"dele"},{"surface":"name","pos":"noun","ipa":"/neɪm/","gloss":"nome"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"Carlos","pos":"proper noun","ipa":"/ˈkɑːrloʊs/","gloss":"Carlos"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-05-04', 'lesson-first-sentences-a1-05', 4, 'sentence', 'Her car is red.', 'O carro dela é vermelho.', '/hɜːr kɑːr ɪz rɛd/', '"Her" = dela.', '[]'::jsonb, '[{"surface":"Her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"red","pos":"adjective","ipa":"/rɛd/","gloss":"vermelho"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-05-05', 'lesson-first-sentences-a1-05', 5, 'sentence', 'Our house is small.', 'Nossa casa é pequena.', '/aʊər haʊs ɪz smɔːl/', '"Our" = nosso/nossa.', '[]'::jsonb, '[{"surface":"Our","pos":"determiner","ipa":"/aʊər/","gloss":"nosso"},{"surface":"house","pos":"noun","ipa":"/haʊs/","gloss":"casa"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"small","pos":"adjective","ipa":"/smɔːl/","gloss":"pequeno"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-05-06', 'lesson-first-sentences-a1-05', 6, 'sentence', 'Their kids are very nice.', 'Os filhos deles são muito legais.', '/ðɛr kɪdz ɑːr ˈvɛri naɪs/', '"Their" = deles/delas. Soa igual a "there" e "they''re".', '[]'::jsonb, '[{"surface":"Their","pos":"determiner","ipa":"/ðɛr/","gloss":"deles, delas"},{"surface":"kids","pos":"noun","ipa":"/kɪdz/","gloss":"crianças, filhos"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"very","pos":"adverb","ipa":"/ˈvɛri/","gloss":"muito"},{"surface":"nice","pos":"adjective","ipa":"/naɪs/","gloss":"prazer; legal"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-05-07', 'lesson-first-sentences-a1-05', 7, 'sentence', 'That''s my coffee.', 'Esse é o meu café.', '/ðæts maɪ ˈkɔːfi/', '"That" = aquele/esse (longe). "That''s" = "that is".', '[]'::jsonb, '[{"surface":"That''s","pos":"pronoun","ipa":"/ðæts/","gloss":"isso é"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-05-08', 'lesson-first-sentences-a1-05', 8, 'sentence', 'These are my friends.', 'Estes são meus amigos.', '/ðiːz ɑːr maɪ frɛndz/', 'Plural de "this" = "these"; de "that" = "those".', '[]'::jsonb, '[{"surface":"These","pos":"determiner","ipa":"/ðiːz/","gloss":"estes, estas"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"friends","pos":"noun","ipa":"/frɛndz/","gloss":"amigos"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-05-09', 'lesson-first-sentences-a1-05', 9, 'sentence', 'Whose bag is this?', 'De quem é esta bolsa?', '/huːz bæɡ ɪz ðɪs/', '"Whose" = de quem.', '[]'::jsonb, '[{"surface":"Whose","pos":"pronoun","ipa":"/huːz/","gloss":"de quem"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-05-10', 'lesson-first-sentences-a1-05', 10, 'sentence', 'It''s mine.', 'É meu.', '/ɪts maɪn/', 'Sem substantivo depois, use "mine, yours, his, hers, ours, theirs".', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"mine","pos":"pronoun","ipa":"/maɪn/","gloss":"meu, minha (sem substantivo)"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-first-sentences-a1-06-01', 'lesson-first-sentences-a1-06', 1, 'sentence', 'I wake up at seven.', 'Eu acordo às sete.', '/aɪ weɪk ʌp æt ˈsɛvən/', 'Presente simples para rotina. "At" + hora.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"wake","pos":"verb","ipa":"/weɪk/","gloss":"acordar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"seven","pos":"numeral","ipa":"/ˈsɛvən/","gloss":"sete"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-06-02', 'lesson-first-sentences-a1-06', 2, 'sentence', 'She works in a hospital.', 'Ela trabalha num hospital.', '/ʃiː wɜːrks ɪn ə ˈhɑːspɪtəl/', 'Com he/she/it o verbo ganha "-s": "works".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"works","pos":"verb","ipa":"/wɜːrks/","gloss":"funciona, serve"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"hospital","pos":"noun","ipa":"/ˈhɑːspɪtəl/","gloss":"hospital"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-06-03', 'lesson-first-sentences-a1-06', 3, 'sentence', 'We live in Brazil.', 'Moramos no Brasil.', '/wiː lɪv ɪn brəˈzɪl/', '"Live in" + cidade ou país, sem artigo.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"live","pos":"verb","ipa":"/lɪv/","gloss":"morar, viver"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"Brazil","pos":"proper noun","ipa":"/brəˈzɪl/","gloss":"Brasil"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-06-04', 'lesson-first-sentences-a1-06', 4, 'sentence', 'He goes to the gym every day.', 'Ele vai à academia todo dia.', '/hiː ɡoʊz tuː ðə dʒɪm ˈɛvri deɪ/', '"Go" com he/she/it vira "goes".', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"goes","pos":"verb","ipa":"/ɡoʊz/","gloss":"vai"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"gym","pos":"noun","ipa":"/dʒɪm/","gloss":"academia"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-06-05', 'lesson-first-sentences-a1-06', 5, 'sentence', 'My father watches the news at night.', 'Meu pai assiste ao jornal à noite.', '/maɪ ˈfɑːðər ˈwɑːtʃɪz ðə nuːz æt naɪt/', 'Verbos terminados em "-ch", "-sh", "-s" ganham "-es": "watches".', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"father","pos":"noun","ipa":"/ˈfɑːðər/","gloss":"pai"},{"surface":"watches","pos":"verb","ipa":"/ˈwɑːtʃɪz/","gloss":"assiste"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"news","pos":"noun","ipa":"/nuːz/","gloss":"notícia(s)"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-06-06', 'lesson-first-sentences-a1-06', 6, 'sentence', 'I usually take the bus.', 'Eu geralmente pego o ônibus.', '/aɪ ˈjuːʒuəli teɪk ðə bʌs/', 'Advérbios de frequência antes do verbo: always, usually, sometimes, never.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"usually","pos":"adverb","ipa":"/ˈjuːʒuəli/","gloss":"geralmente"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-06-07', 'lesson-first-sentences-a1-06', 7, 'sentence', 'She studies English on Mondays.', 'Ela estuda inglês às segundas.', '/ʃiː ˈstʌdiz ˈɪŋɡlɪʃ ɑːn ˈmʌndeɪz/', 'Consoante + "y" vira "-ies": study → studies.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"studies","pos":"verb","ipa":"/ˈstʌdiz/","gloss":"estuda"},{"surface":"English","pos":"proper noun","ipa":"/ˈɪŋɡlɪʃ/","gloss":"inglês"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Mondays","pos":"proper noun","ipa":"/ˈmʌndeɪz/","gloss":"segundas-feiras"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-06-08', 'lesson-first-sentences-a1-06', 8, 'sentence', 'It rains a lot in April.', 'Chove muito em abril.', '/ɪt reɪnz ə lɑːt ɪn ˈeɪprəl/', 'Fenômenos da natureza com "it": "it rains", "it snows".', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"rains","pos":"verb","ipa":"/reɪnz/","gloss":"chove"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"lot","pos":"noun","ipa":"/lɑːt/","gloss":"muito (a lot)"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"April","pos":"proper noun","ipa":"/ˈeɪprəl/","gloss":"abril"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-06-09', 'lesson-first-sentences-a1-06', 9, 'sentence', 'They have lunch at noon.', 'Eles almoçam ao meio-dia.', '/ðeɪ hæv lʌntʃ æt nuːn/', '"Have lunch" = almoçar. Com he/she/it: "has lunch".', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"lunch","pos":"noun","ipa":"/lʌntʃ/","gloss":"almoço"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"noon","pos":"noun","ipa":"/nuːn/","gloss":"meio-dia"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-06-10', 'lesson-first-sentences-a1-06', 10, 'sentence', 'I never drink coffee at night.', 'Nunca bebo café à noite.', '/aɪ ˈnɛvər drɪŋk ˈkɔːfi æt naɪt/', '"Never" já é negativo: o verbo fica afirmativo.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"never","pos":"adverb","ipa":"/ˈnɛvər/","gloss":"nunca"},{"surface":"drink","pos":"verb","ipa":"/drɪŋk/","gloss":"beber"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-first-sentences-a1-07-01', 'lesson-first-sentences-a1-07', 1, 'sentence', 'Do you speak English?', 'Você fala inglês?', '/duː juː spiːk ˈɪŋɡlɪʃ/', 'Pergunta no presente: "do" + sujeito + verbo base.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"speak","pos":"verb","ipa":"/spiːk/","gloss":"falar"},{"surface":"English","pos":"proper noun","ipa":"/ˈɪŋɡlɪʃ/","gloss":"inglês"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-07-02', 'lesson-first-sentences-a1-07', 2, 'sentence', 'Does she live near here?', 'Ela mora perto daqui?', '/dʌz ʃiː lɪv nɪr hɪr/', 'Com he/she/it use "does", e o verbo volta à base: "does she live" (não "lives").', '[]'::jsonb, '[{"surface":"Does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"live","pos":"verb","ipa":"/lɪv/","gloss":"morar, viver"},{"surface":"near","pos":"preposition","ipa":"/nɪr/","gloss":"perto de"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-07-03', 'lesson-first-sentences-a1-07', 3, 'sentence', 'I don''t eat meat.', 'Eu não como carne.', '/aɪ doʊnt iːt miːt/', 'Negativa: "don''t" + verbo base.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"eat","pos":"verb","ipa":"/iːt/","gloss":"comer"},{"surface":"meat","pos":"noun","ipa":"/miːt/","gloss":"carne"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-07-04', 'lesson-first-sentences-a1-07', 4, 'sentence', 'He doesn''t like coffee.', 'Ele não gosta de café.', '/hiː ˈdʌzənt laɪk ˈkɔːfi/', '"Doesn''t" + verbo base: "doesn''t like" (não "likes").', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"doesn''t","pos":"verb","ipa":"/ˈdʌzənt/","gloss":"não (does not)"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-07-05', 'lesson-first-sentences-a1-07', 5, 'sentence', 'What do you do?', 'O que você faz? (profissão)', '/wʌt duː juː duː/', 'O primeiro "do" é auxiliar; o segundo é o verbo fazer. Pergunta sobre trabalho.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-07-06', 'lesson-first-sentences-a1-07', 6, 'sentence', 'Where do you work?', 'Onde você trabalha?', '/wɛr duː juː wɜːrk/', 'Palavra de pergunta + do + sujeito + verbo.', '[]'::jsonb, '[{"surface":"Where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-07-07', 'lesson-first-sentences-a1-07', 7, 'sentence', 'How often do you exercise?', 'Com que frequência você se exercita?', '/haʊ ˈɔːfən duː juː ˈɛksərsaɪz/', '"How often" pergunta frequência.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"often","pos":"adverb","ipa":"/ˈɔːfən/","gloss":"frequentemente"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"exercise","pos":"verb","ipa":"/ˈɛksərsaɪz/","gloss":"exercitar-se"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-07-08', 'lesson-first-sentences-a1-07', 8, 'sentence', 'Yes, I do.', 'Sim.', '/jɛs aɪ duː/', 'Resposta curta com o auxiliar: "Yes, I do" / "No, I don''t".', '[]'::jsonb, '[{"surface":"Yes","pos":"interjection","ipa":"/jɛs/","gloss":"sim"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-07-09', 'lesson-first-sentences-a1-07', 9, 'sentence', 'We don''t have a car.', 'Não temos carro.', '/wiː doʊnt hæv ə kɑːr/', '"Have" também usa "don''t" na negativa.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-07-10', 'lesson-first-sentences-a1-07', 10, 'sentence', 'What time does the store open?', 'Que horas a loja abre?', '/wʌt taɪm dʌz ðə stɔːr ˈoʊpən/', 'Horários fixos: presente simples com "does".', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"store","pos":"noun","ipa":"/stɔːr/","gloss":"loja, mercado"},{"surface":"open","pos":"verb","ipa":"/ˈoʊpən/","gloss":"abrir"}]'::jsonb, NULL, NULL)
